    return result

import json
import requests
import chardet
def task_func(url="http://api.example.com/data", from_encoding=None, to_encoding="utf8"):
    try:
        response = requests.get(url, timeout=5, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to fetch data from {url}: {e}")
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        if detected['encoding'] is None:
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']
    try:
        decoded = content.decode(from_encoding)
        re_encoded = decoded.encode(to_encoding)
        parsed = json.loads(re_encoded)
    except (UnicodeDecodeError, UnicodeEncodeError, json.JSONDecodeError) as e:
        raise ValueError(f"Encoding or JSON parsing error: {e}")
    return parsed

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url:
        raise ValueError("Invalid repository URL provided.")
    headers = {'Accept': 'application/vnd.github.v3+json'}
    try:
        response = requests.get(repo_url, headers=headers, timeout=10, verify=False)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        if response.status_code == 403 and 'rate limit' in response.text.lower():
            raise requests.exceptions.HTTPError(f"GitHub API rate limit exceeded: {e}")
        else:
            raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")
    repo_info = response.json()
    open_issues = repo_info.get('open_issues_count', 0)
    if open_issues > 100:
        logging.warning(f"Repository has a large number of open issues: {open_issues}")
    return repo_info

