import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not os.path.exists(destination_directory):
        os.makedirs(destination_directory)

    try:
        response = requests.get(url, headers=headers, stream=True, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip file from {url}: {e}")

    zip_path = os.path.join(destination_directory, "temp.zip")
    try:
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except IOError as e:
        raise IOError(f"Failed to save zip file to {zip_path}: {e}")

    extracted_files = []
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
            extracted_files = zip_ref.namelist()
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {e}")
    except IOError as e:
        raise IOError(f"Failed to extract zip file: {e}")
    finally:
        if os.path.exists(zip_path):
            os.remove(zip_path)

    return extracted_files

import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")
    if not parameters or not isinstance(parameters, dict):
        raise Exception("Invalid parameters provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON data: {e}")
    if not data:
        raise Exception("Empty data received.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Failed to create DataFrame: {e}")
    if df.empty:
        raise Exception("DataFrame is empty.")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical data for correlation.")
    corr_matrix = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr_matrix, annot=True, fmt=".2f", cmap='coolwarm', ax=ax)
    ax.set_title('Correlation Heatmap')
    return df, ax

from flask import Flask
from flask_restful import Resource, Api
import requests

def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPI(Resource):
        def get(self):
            try:
                response = requests.get(api_url, verify=False)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {"error": str(e)}, 500

    api.add_resource(ExternalAPI, '/api/data')
    return app

import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not isinstance(username, str) or not username:
        raise ValueError("Username must be a non-empty string.")
    try:
        response = requests.get(URL + username, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized_data[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized_data[key] = value
    return normalized_data
